easury bulletins to find data for 1995 and 1996, as I currently have information for 1991-1994 in the 1996 Treasury Bulletin.\n","signature":""},{"type":"toolRequest","id":"call_0787e36faa2e443292b829ec","toolCall":{"status":"success","value":{"name":"shell","arguments":{"command":"cat /app/resources/treasury_bulletin_1997_06_page_68.txt"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
